// @FIGURE_CODE_BEGIN
/* ELEMENT SPEC
   halo shell      -> SphereGeometry(1,72,36,0,2PI,0,PI/2) scale 1.035*(3,2,2), BackSide, #f2f4f6
   outer blue dome -> same sphere, scale (3,2,2), FrontSide, vertex gradient #2f7fc1 -> #eaf2f9,
                      clipped: removed where (y < 1.0 AND near-camera half)  [clipIntersection]
   inner tan dome  -> same sphere, scale 0.985*(3,2,2), BackSide, gradient #d9c79a -> #f2e6c6
   cut rim strip   -> TubeGeometry elliptical ring at y=1.0 on r=1 shell, #f2f4f6
   inner bands     -> 2 thin elliptical TubeGeometry rings on inner wall, faint tan
   floor           -> CircleGeometry(1,80) rot -PI/2, scale(3,2,1), gradient #ecdfba -> #f7edd4
   slab            -> CylinderGeometry(1,1,0.45,80) scale(3.21,1,2.14) #4a4a4a
   slab top rim    -> RingGeometry(1.0,1.07,80) rot -PI/2 scale(3,2,1) #8a8a8a
   foci dots       -> SphereGeometry(0.09) at (+-sqrt5,0.02,0) #16324f
   rays            -> 6 x (2 TubeGeometry legs, radius .035) navy #1c4e80
   arrowheads      -> ConeGeometry(0.085,0.22) at 55% of each leg, navy
   pulses          -> SphereGeometry(0.075) + 2 trail spheres, #7fd0ff
*/

renderer.localClippingEnabled = true;

const CUT_Y = 1.0;
const A = 3, B = 2, C = 2;           // semi-axes
const FX = Math.sqrt(A * A - B * B); // 2.236
const NAVY = 0x1c4e80, CYAN = 0x2f8fd8;

/* ── helpers ─────────────────────────────────────────────────────────── */
function paintGradient(geo, fn) {
  const pos = geo.attributes.position;
  const col = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    fn(pos.getX(i), pos.getY(i), pos.getZ(i), c);
    col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return geo;
}
const CA = new THREE.Color(), CB = new THREE.Color();
function ramp(hexLo, hexHi, t, out) {
  CA.setHex(hexLo); CB.setHex(hexHi);
  out.copy(CA).lerp(CB, Math.max(0, Math.min(1, t)));
}
function ellipseRing(semiX, semiZ, y, tubeR, color, opacity) {
  const pts = [];
  for (let i = 0; i <= 160; i++) {
    const a = (i / 160) * Math.PI * 2;
    pts.push(new THREE.Vector3(semiX * Math.cos(a), y, semiZ * Math.sin(a)));
  }
  const curve = new THREE.CatmullRomCurve3(pts, true);
  const m = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 200, tubeR, 8, true),
    new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity })
  );
  return m;
}

/* ── dome shells ─────────────────────────────────────────────────────── */
const domeGeoSrc = () => new THREE.SphereGeometry(1, 72, 36, 0, Math.PI * 2, 0, Math.PI / 2);

// halo (shell thickness seen at the silhouette)
const halo = new THREE.Mesh(
  domeGeoSrc(),
  new THREE.MeshBasicMaterial({ color: 0xf2f4f6, side: THREE.BackSide })
);
halo.scale.set(A * 1.035, B * 1.035, C * 1.035);
scene.add(halo);

// outer blue shell, cut away toward the viewer below CUT_Y
const planeTop = new THREE.Plane(new THREE.Vector3(0, 1, 0), -CUT_Y / B); // local space? -> world below
planeTop.constant = -CUT_Y;
const planeFar = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
const outerGeo = paintGradient(domeGeoSrc(), (x, y, z, c) => {
  ramp(0xeaf2f9, 0x2f7fc1, Math.pow(Math.max(0, y), 0.75), c);
});
const outerMat = new THREE.MeshBasicMaterial({
  vertexColors: true, side: THREE.FrontSide,
  clippingPlanes: [planeTop, planeFar], clipIntersection: true
});
const outer = new THREE.Mesh(outerGeo, outerMat);
outer.scale.set(A, B, C);
scene.add(outer);

// inner tan surface (back side => we see the far interior wall)
const innerGeo = paintGradient(domeGeoSrc(), (x, y, z, c) => {
  ramp(0xf2e6c6, 0xd9c79a, Math.pow(Math.max(0, y), 0.7), c);
});
const inner = new THREE.Mesh(innerGeo, new THREE.MeshBasicMaterial({
  vertexColors: true, side: THREE.BackSide
}));
inner.scale.set(A * 0.985, B * 0.985, C * 0.985);
scene.add(inner);

// white rim strip along the cut edge (only the front arc is unoccluded)
{
  const f = Math.sqrt(1 - (CUT_Y / B) * (CUT_Y / B));
  scene.add(ellipseRing(A * f, C * f, CUT_Y, 0.05, 0xf2f4f6, 1));
}
// faint banding on the inner wall
[[0.52, 0xcdb98c, 0.55], [0.88, 0xe6d6ab, 0.45]].forEach(([yy, col, op]) => {
  const k = 0.982;
  const f = Math.sqrt(Math.max(0.001, 1 - (yy / (B * k)) * (yy / (B * k))));
  scene.add(ellipseRing(A * k * f, C * k * f, yy, 0.018, col, op));
});

/* ── floor + base slab ───────────────────────────────────────────────── */
const floorGeo = paintGradient(new THREE.CircleGeometry(1, 80), (x, y, z, c) => {
  ramp(0xecdfba, 0xf7edd4, (-y + 1) / 2, c);   // local +y -> world -z (back)
});
const floor = new THREE.Mesh(floorGeo, new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide }));
floor.rotation.x = -Math.PI / 2;
floor.scale.set(A, C, 1);
scene.add(floor);

const slabGeo = paintGradient(new THREE.CylinderGeometry(1, 1, 0.45, 80, 1, false), (x, y, z, c) => {
  ramp(0x3a3a3a, 0x565656, (y + 0.225) / 0.45, c);
});
const slab = new THREE.Mesh(slabGeo, new THREE.MeshBasicMaterial({ vertexColors: true }));
slab.position.y = -0.225;
slab.scale.set(A * 1.07, 1, C * 1.07);
scene.add(slab);

const rim = new THREE.Mesh(
  new THREE.RingGeometry(1.0, 1.07, 80),
  new THREE.MeshBasicMaterial({ color: 0x8a8a8a, side: THREE.DoubleSide })
);
rim.rotation.x = -Math.PI / 2;
rim.position.y = 0.003;
rim.scale.set(A, C, 1);
scene.add(rim);

/* ── foci ────────────────────────────────────────────────────────────── */
const Fp = new THREE.Vector3(-FX, 0.02, 0);
const Fr = new THREE.Vector3(FX, 0.02, 0);
const dotMat = new THREE.MeshBasicMaterial({ color: 0x16324f, depthTest: false });
[Fp, Fr].forEach(p => {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.09, 20, 14), dotMat);
  m.position.copy(p); m.renderOrder = 12;
  scene.add(m);
});

/* ── rays ────────────────────────────────────────────────────────────── */
const rawBounce = [
  [-1.4, 1.82, 0.3], [-0.2, 1.99, -0.35], [0.0, 2.0, 0.55],
  [1.3, 1.83, -0.5], [2.1, 1.44, 0.4], [-2.3, 1.29, -0.45]
];
function snap(p) {
  const u = new THREE.Vector3(p[0] / A, p[1] / B, p[2] / C).normalize();
  return new THREE.Vector3(u.x * A, Math.abs(u.y) * B, u.z * C);
}
const bounce = rawBounce.map(snap);

function legMesh(a, b, mat) {
  return new THREE.Mesh(new THREE.TubeGeometry(new THREE.LineCurve3(a, b), 1, 0.035, 10, false), mat);
}
function arrowMesh(a, b, mat) {
  const dir = new THREE.Vector3().subVectors(b, a).normalize();
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.085, 0.24, 14), mat);
  cone.position.copy(a).lerp(b, 0.55);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  return cone;
}

const rays = [];
bounce.forEach((P, i) => {
  const mat = new THREE.MeshBasicMaterial({ color: NAVY, depthTest: false, transparent: false, opacity: 1 });
  const g = new THREE.Group();
  const parts = [legMesh(Fp, P, mat), legMesh(P, Fr, mat), arrowMesh(Fp, P, mat), arrowMesh(P, Fr, mat)];
  parts.forEach(m => { m.renderOrder = 10; g.add(m); });
  scene.add(g);

  const L1 = Fp.distanceTo(P), L2 = P.distanceTo(Fr);

  // pulse + trail
  const pulseMats = [];
  const pulses = [];
  for (let k = 0; k < 3; k++) {
    const pm = new THREE.MeshBasicMaterial({ color: 0x7fd0ff, depthTest: false, transparent: true, opacity: 1 - k * 0.33 });
    const s = new THREE.Mesh(new THREE.SphereGeometry(0.075 - k * 0.018, 14, 10), pm);
    s.renderOrder = 14; s.visible = false;
    scene.add(s); pulses.push(s); pulseMats.push(pm);
  }

  const entry = { group: g, mat, P, L1, L2, pulses, index: i };
  rays.push(entry);

  parts.forEach(m => registerInteractive(m, {
    title: 'Sound ray ' + (i + 1),
    tooltip: 'Click: highlight this launch angle',
    body: "This ray leaves F&prime;, reflects once off the inner dome, and arrives at F. Its two legs total 2a = 6 units \u2014 the same as every other ray, so all pulses reach F at the same instant.",
    onClick: () => { selected = i; highlight = true; refresh(); syncUI(); }
  }));
});

function pointAt(r, s) {
  if (s <= r.L1) return new THREE.Vector3().copy(Fp).lerp(r.P, s / r.L1);
  return new THREE.Vector3().copy(r.P).lerp(Fr, Math.min(1, (s - r.L1) / r.L2));
}

/* ── camera ──────────────────────────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 90, elevationDeg: 18, rollDeg: 0, heightFraction: 0.62 });
controls.minPolarAngle = THREE.MathUtils.degToRad(20);
controls.maxPolarAngle = THREE.MathUtils.degToRad(85);

/* ── labels ──────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,\'Times New Roman\',serif;font-style:italic;';
addLabel('<span style="' + SER + '">F&prime;</span>', Fp, { fontSize: '19px', offset: [-16, 20] });
addLabel('<span style="' + SER + '">F</span>', Fr, { fontSize: '19px', offset: [18, 20] });

/* ── state + UI ──────────────────────────────────────────────────────── */
let mode = 'single';
let selected = 0;
let highlight = true;
let playing = false;
let s = 0;
const SPEED = 2.6;

function refresh() {
  rays.forEach((r, i) => {
    const isSel = i === selected;
    let vis, col, op;
    if (mode === 'single') { vis = isSel; col = NAVY; op = 1; }
    else if (highlight) { vis = true; col = isSel ? CYAN : NAVY; op = isSel ? 1 : 0.28; }
    else { vis = true; col = NAVY; op = 1; }
    r.group.visible = vis;
    r.mat.color.setHex(col);
    r.mat.opacity = op;
    r.mat.transparent = op < 1;
    r.mat.needsUpdate = true;
    if (!vis || !playing) r.pulses.forEach(p => p.visible = false);
  });
}

const btnSingle = document.getElementById('btnSingle');
const btnAll = document.getElementById('btnAll');
const btnPulse = document.getElementById('btnPulse');
const rayBtns = document.getElementById('rayBtns');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

const numBtns = [];
for (let i = 0; i < 6; i++) {
  const b = document.createElement('button');
  b.textContent = String(i + 1);
  b.style.minWidth = '26px';
  b.addEventListener('click', () => { selected = i; highlight = true; refresh(); syncUI(); });
  rayBtns.appendChild(b);
  numBtns.push(b);
}

function syncUI() {
  btnSingle.classList.toggle('active', mode === 'single');
  btnAll.classList.toggle('active', mode === 'all');
  numBtns.forEach((b, i) => b.classList.toggle('active', i === selected));
  btnPulse.textContent = playing ? '\u25A0 Stop pulse' : '\u25B6 Play sound pulse from F\u2032';
  btnPulse.classList.toggle('active', playing);
}

btnSingle.addEventListener('click', () => { mode = 'single'; highlight = true; s = 0; refresh(); syncUI(); });
btnAll.addEventListener('click', () => { mode = 'all'; highlight = false; s = 0; refresh(); syncUI(); });
btnPulse.addEventListener('click', () => { playing = !playing; s = 0; refresh(); syncUI(); });

/* ── demo steps ──────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'One whispered ray', n: "A single sound ray leaves the left focus F\u2032, rises to the inner dome, and reflects straight down to the right focus F.", m: 'single', p: false, h: true },
  { t: 'Watch it travel', n: 'Play the pulse: the wavefront climbs to the dome, turns at the bounce point, and arrives at F.', m: 'single', p: true, h: true },
  { t: 'The whole fan', n: 'Six different launch angles hit six different spots on the dome, yet every one comes back to F \u2014 and all the pulses arrive at the same instant.', m: 'all', p: true, h: false }
];
let step = 0;
function goToStep(i) {
  step = Math.max(0, Math.min(STEPS.length - 1, i));
  const st = STEPS[step];
  mode = st.m; playing = st.p; highlight = st.h; s = 0;
  stepTitle.textContent = (step + 1) + '. ' + st.t;
  stepText.textContent = st.n;
  refresh(); syncUI();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(step - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(step + 1));
goToStep(0);

/* ── per-frame: cutaway follows the camera, pulses advance ───────────── */
const _vd = new THREE.Vector3();
let _last = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;

  camera.getWorldDirection(_vd);
  _vd.y = 0;
  if (_vd.lengthSq() > 1e-6) { _vd.normalize(); planeFar.normal.copy(_vd); planeFar.constant = 0; }

  if (playing) {
    s += dt * SPEED;
    if (s > 2 * A + 0.9) s = 0;
    rays.forEach(r => {
      if (!r.group.visible) { r.pulses.forEach(p => p.visible = false); return; }
      r.pulses.forEach((p, k) => {
        const sk = s - k * 0.16;
        if (sk < 0 || sk > 2 * A) { p.visible = false; return; }
        p.visible = true;
        p.position.copy(pointAt(r, sk));
      });
    });
  }
})();
